    'white': (255, 255, 255),
    'black': (0, 0, 0),
    'red': (255, 0, 0),
    'green': (0, 255, 0)
}

pygame.init()
screen = pygame.display.set_mode((WIDTH, HEIGHT))
clock = pygame.time.Clock()

player1_snake = [[WIDTH/2, HEIGHT/2], [WIDTH/2-BLOCK_SIZE, HEIGHT/2], [WIDTH/2-2*BLOCK_SIZE, HEIGHT/2]]
player2_snake = [[WIDTH//4*3, HEIGHT//2], [WIDTH//4*3-BLOCK_SIZE, HEIGHT/2], [WIDTH//4*3-2*BLOCK_SIZE, HEIGHT/2]]

food_position = None
score1, score2 = 0, 0

def draw_snake(snake):
    for segment in snake:
        pygame.draw.rect(screen, COLORS['green'], pygame.Rect(segment[0], segment[1], BLOCK_SIZE, BLOCK_SIZE))

def draw_food(position):
    pygame.draw.rect(screen, COLORS['red'], pygame.Rect(position[0], position[1], BLOCK_SIZE, BLOCK_SIZE))

def check_collision():
    global score1, score2
    if player1_snake[0] in [seg for seg in player2_snake]:
        score2 += 1
        player1_snake = [[WIDTH/2, HEIGHT/2], [WIDTH/2-BLOCK_SIZE, HEIGHT/2]]
    elif any(segment == player1_snake[0] for segment in player1_snake[1:]):
        score1 += 1
        player1_snake = [[WIDTH/2, HEIGHT/2], [WIDTH/2-BLOCK_SIZE, HEIGHT/2]]

    if any(segment == player2_snake[0] for segment in player2_snake[1:]):
        score1 += 1
    elif any(segment == (player2_snake[0][0], player1_snake[0][1]) for segment in player2_snake[1:]):
        score2 += 1

running = True
