            running = False

        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_w and player1_snake[0][1] > BLOCK_SIZE:
                player1_snake.insert(0, [player1_snake[0][0], player1_snake[0][1]-BLOCK_SIZE])
            elif event.key == pygame.K_a and player1_snake[0][0] < WIDTH - BLOCK_SIZE:
                player1_snake.insert(0, [player1_snake[0][0]-BLOCK_SIZE, player1_snake[0][1]])
            elif event.key == pygame.K_s and player1_snake[0][1] < HEIGHT - BLOCK_SIZE:
                player1_snake.insert(0, [player1_snake[0][0], player1_snake[0][1]+BLOCK_SIZE])
            elif event.key == pygame.K_d and player1_snake[0][0] > BLOCK_SIZE:
                player1_snake.insert(0, [player1_snake[0][0]-BLOCK_SIZE, player1_snake[0][1]])

        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_UP and player2_snake[0][1] > BLOCK_SIZE:
                player2_snake.insert(0, [player2_snake[0][0], player2_snake[0][1]-BLOCK_SIZE])
            elif event.key == pygame.K_DOWN and player2_snake[0][1] < HEIGHT - BLOCK_SIZE:
