            elif event.key == pygame.K_LEFT and player2_snake[0][0] > BLOCK_SIZE:
                player2_snake.insert(0, [player2_snake[0][0]-BLOCK_SIZE, player2_snake[0][1]])
            elif event.key == pygame.K_RIGHT and player2_snake[0][0] < WIDTH - BLOCK_SIZE:
                player2_snake.insert(0, [player2_snake[0][0]+BLOCK_SIZE, player2_snake[0][1]])

        if food_position is not None:
